#!/usr/bin/env swift
// Mechanical sprite slicing / asset packaging; the artwork is generated by imagegen.
// Run from the repository root: swift scripts/package-marr-icons.swift
import AppKit

struct Manifest: Decodable {
    struct Source: Decodable { let file: String; let columns: Int; let rows: Int; let icons: [String]; let xCuts: [Int]?; let yCuts: [Int]? }
    let sources: [Source]
    let assetPrefix: String
}
let root = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
let design = root.appendingPathComponent("DesignAssets/MarrIcons")
let manifest = try JSONDecoder().decode(Manifest.self, from: Data(contentsOf: design.appendingPathComponent("manifest.json")))
var exported = Set<String>()
for source in manifest.sources {
    let bitmap = NSBitmapImageRep(data: try Data(contentsOf: design.appendingPathComponent(source.file)))!
    let cg = bitmap.cgImage!
    for (index, name) in source.icons.enumerated() {
        guard exported.insert(name).inserted else { continue }
        let x0 = source.xCuts?[index % source.columns] ?? (index % source.columns * bitmap.pixelsWide / source.columns)
        let x1 = source.xCuts?[index % source.columns + 1] ?? ((index % source.columns + 1) * bitmap.pixelsWide / source.columns)
        let y0 = source.yCuts?[index / source.columns] ?? (index / source.columns * bitmap.pixelsHigh / source.rows)
        let y1 = source.yCuts?[index / source.columns + 1] ?? ((index / source.columns + 1) * bitmap.pixelsHigh / source.rows)
        var left = x1, right = x0, top = y1, bottom = y0
        for y in y0..<y1 { for x in x0..<x1 {
            if (bitmap.colorAt(x: x, y: y)?.alphaComponent ?? 0) > 0.08 {
                left = min(left, x); right = max(right, x)
                top = min(top, y); bottom = max(bottom, y)
            }
        } }
        precondition(left > x0 && right < x1 - 1 && top > y0 && bottom < y1 - 1, "Clipped cell: \(name)")
        let crop = cg.cropping(to: CGRect(x: left - 1, y: top - 1, width: right - left + 3, height: bottom - top + 3))!
        let asset = root.appendingPathComponent("Marr/Assets.xcassets/\(manifest.assetPrefix)\(name).imageset")
        try FileManager.default.createDirectory(at: asset, withIntermediateDirectories: true)
        var images: [[String: String]] = []
        for scale in 1...3 {
            // 32-point master supports the largest empty states without upscaling.
            let size = 32 * scale
            let output = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: size, pixelsHigh: size,
                bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0)!
            let context = NSGraphicsContext(bitmapImageRep: output)!.cgContext
            context.interpolationQuality = .high
            let ratio = CGFloat(size) * 0.84 / CGFloat(max(crop.width, crop.height))
            let width = CGFloat(crop.width) * ratio, height = CGFloat(crop.height) * ratio
            context.draw(crop, in: CGRect(x: (CGFloat(size) - width) / 2, y: (CGFloat(size) - height) / 2, width: width, height: height))
            let filename = "\(name)@\(scale)x.png"
            try output.representation(using: .png, properties: [:])!.write(to: asset.appendingPathComponent(filename))
            images.append(["idiom": "universal", "filename": filename, "scale": "\(scale)x"])
        }
        let contents: [String: Any] = ["images": images, "info": ["author": "xcode", "version": 1],
                                       "properties": ["template-rendering-intent": "template"]]
        try JSONSerialization.data(withJSONObject: contents, options: [.prettyPrinted, .sortedKeys])
            .write(to: asset.appendingPathComponent("Contents.json"))
    }
}
print("Packaged \(exported.count) template icons at 1x / 2x / 3x.")

// Contact sheets are review artifacts, composed from the exact shipped pixels.
let ordered = manifest.sources.flatMap(\.icons).reduce(into: [String]()) { names, name in
    if !names.contains(name) { names.append(name) }
}
for dark in [false, true] {
    let width = 960, height = 1200
    let sheet = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: width, pixelsHigh: height,
        bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
        colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0)!
    let graphics = NSGraphicsContext(bitmapImageRep: sheet)!
    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = graphics
    let background = dark ? NSColor(calibratedWhite: 0.13, alpha: 1) : NSColor(calibratedWhite: 0.98, alpha: 1)
    let foreground = dark ? NSColor(calibratedWhite: 0.88, alpha: 1) : NSColor(calibratedWhite: 0.22, alpha: 1)
    background.setFill(); NSRect(x: 0, y: 0, width: width, height: height).fill()
    ("Marr / Outline Icons" as NSString).draw(at: NSPoint(x: 32, y: height - 52),
        withAttributes: [.font: NSFont.systemFont(ofSize: 24, weight: .medium), .foregroundColor: foreground])
    ("94 original glyphs · 24 pt + 16 pt · template color" as NSString).draw(at: NSPoint(x: 32, y: height - 77),
        withAttributes: [.font: NSFont.systemFont(ofSize: 13), .foregroundColor: foreground])
    for (index, name) in ordered.enumerated() {
        let bitmap = NSBitmapImageRep(data: try Data(contentsOf: root.appendingPathComponent(
            "Marr/Assets.xcassets/MarrIcon-\(name).imageset/\(name)@2x.png")))!
        let x = CGFloat(index % 8) * 120, y = CGFloat(height - 140 - index / 8 * 90)
        for (offset, size): (CGFloat, CGFloat) in [(34, 24), (72, 16)] {
            let rect = CGRect(x: x + offset, y: y, width: size, height: size)
            graphics.cgContext.saveGState()
            graphics.cgContext.clip(to: rect, mask: bitmap.cgImage!)
            graphics.cgContext.setFillColor(foreground.cgColor)
            graphics.cgContext.fill(rect)
            graphics.cgContext.restoreGState()
        }
        let paragraph = NSMutableParagraphStyle(); paragraph.alignment = .center
        (name as NSString).draw(in: NSRect(x: x + 2, y: y - 28, width: 116, height: 20),
            withAttributes: [.font: NSFont.systemFont(ofSize: 10), .foregroundColor: foreground, .paragraphStyle: paragraph])
    }
    NSGraphicsContext.restoreGraphicsState()
    try sheet.representation(using: .png, properties: [:])!.write(to: design.appendingPathComponent(dark ? "catalog-dark.png" : "catalog-light.png"))
}
